#include <stdio.h>#include <stdlib.h>#include <time.h>// Función para generar Pascal usando memoria dinámica y evaluarvoid generar_y_evaluar(int n, int x) {    // 1. Memoria Dinámica (arreglo de n+1 elementos)    long long *fila = (long long *)malloc((n + 1) * sizeof(long long));    if (fila == NULL) {        printf("Error de memoria\n");        return;    }    // Inicializar    for (int i = 0; i <= n; i++) fila[i] = 0;    fila[0] = 1;    // 2. Generar Triángulo de Pascal    for (int i = 1; i <= n; i++) {        for (int j = i; j >= 1; j--) {            fila[j] = fila[j] + fila[j - 1];        }    }    // 3. Mostrar Polinomio    printf("Polinomio (x+1)^%d:\n", n);    for (int i = 0; i <= n; i++) {        int potencia = n - i;        if (i > 0) printf(" + ");        if (potencia == 0) printf("%lld", fila[i]);        else if (potencia == 1) printf("%lldx", fila[i]);        else printf("%lldx^%d", fila[i], potencia);    }    printf("\n\n");    // 4. Evaluación paso a paso    printf("Evaluacion paso a paso para x = %d:\n", x);    long long resultado = 0;    long long x_potencia = 1;        // Calcular potencias de x de derecha a izquierda    // (Para hacerlo rápido sin pow())    long long *potencias = (long long *)malloc((n + 1) * sizeof(long long));    potencias[0] = 1;    for (int i = 1; i <= n; i++) {        potencias[i] = potencias[i - 1] * x;    }    for (int i = 0; i <= n; i++) {        int potencia = n - i;        long long valor_termino = fila[i] * potencias[potencia];        resultado += valor_termino;        printf("  %lld * %d^%d = %lld -> Acumulado: %lld\n", fila[i], x, potencia, valor_termino, resultado);    }    printf("\nResultado final f(%d) = %lld\n", x, resultado);    // Liberar memoria    free(fila);    free(potencias);}int main() {    // Prueba con n=5, x=2    generar_y_evaluar(5, 2);    // Medición de tiempo para n=100    printf("\n--- TIEMPO PARA N=100 EN C ---\n");    clock_t inicio = clock();        // Solo generamos para medir (sin imprimir todo)    int n = 100;    long long *fila = (long long *)malloc((n + 1) * sizeof(long long));    for (int i = 0; i <= n; i++) fila[i] = 0;    fila[0] = 1;    for (int i = 1; i <= n; i++) {        for (int j = i; j >= 1; j--) {            fila[j] = fila[j] + fila[j - 1];        }    }    free(fila);        clock_t fin = clock();    double tiempo = ((double)(fin - inicio) / CLOCKS_PER_SEC) * 1000;    printf("Tiempo de generacion de n=100 en C: %.6f milisegundos\n", tiempo);    return 0;}